var subsetXORSum = function(nums) {
    function visit(index, xor) {
        if (index === nums.length) return xor;
        const without = visit(index + 1, xor);
        const withValue = visit(index + 1, xor ^ nums[index]);
        return without + withValue;
    }
    return visit(0, 0);
};

